"use client";

import { useId, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";

import { BlockFrame } from "../parts/block-frame";
import { SearchField } from "./shared/search-field";
import { ROSTER, type Team } from "./shared/roster";
import { PeopleList } from "./team-directory/people-list";
import { ProfilePanel } from "./team-directory/profile-panel";

type Filter = "all" | Team;

const FILTERS: Filter[] = ["all", "Practitioners", "Front desk", "Operations"];

/**
 * The clinic's people in one place: search, filter by team, pick a person,
 * and read their profile with what they work on and how to reach them.
 */
export function TeamDirectory({ className }: { className?: string }) {
  const titleId = useId();
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [selected, setSelected] = useState(ROSTER[0]!.id);

  const needle = query.trim().toLowerCase();
  const searched = ROSTER.filter((person) => !needle || `${person.name} ${person.title} ${person.email}`.toLowerCase().includes(needle));
  const shown = searched.filter((person) => filter === "all" || person.team === filter);
  // When the filter hides the chosen person, the first person still shown takes their place.
  const activeId = shown.some((person) => person.id === selected) ? selected : (shown[0]?.id ?? selected);
  const chosen = ROSTER.find((person) => person.id === activeId) ?? ROSTER[0]!;

  const options = FILTERS.map((value) => {
    const count = value === "all" ? searched.length : searched.filter((person) => person.team === value).length;
    return {
      value,
      label: (
        <span className="flex items-center gap-1.5">
          {value === "all" ? "Everyone" : value}
          <span className="text-xs text-muted-foreground tabular-nums">{count}</span>
        </span>
      ),
    };
  });

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-col gap-3 border-b border-border px-5 py-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <h2 id={titleId} className="text-base font-semibold">
            Directory <span className="font-normal text-muted-foreground">{ROSTER.length} people</span>
          </h2>
          <label className="w-full @md:w-64">
              <span className="sr-only">Search people</span>
              <SearchField placeholder="Search name or role" value={query} onChange={(event) => setQuery(event.target.value)} />
            </label>
        </div>
        <div className="scroll-fade-effect-x scrollbar-none -mx-1 overflow-x-auto px-1 py-1">
          <SegmentedControl aria-label="Team" options={options} value={filter} onValueChange={setFilter} />
        </div>
      </header>
      <div className="grid grid-cols-1 @2xl:grid-cols-[minmax(0,1fr)_minmax(0,1.2fr)]">
        <div className="border-b border-border p-3 @2xl:border-r @2xl:border-b-0">
          {shown.length ? (
            <PeopleList people={shown} selected={activeId} onSelect={setSelected} label="People" />
          ) : (
            <p className="px-3 py-6 text-sm text-muted-foreground">Nobody matches that search in this team.</p>
          )}
          <p aria-live="polite" className="sr-only">
            {shown.length} {shown.length === 1 ? "person" : "people"} shown
          </p>
        </div>
        <div className="p-5">
          <ProfilePanel person={chosen} />
        </div>
      </div>
    </BlockFrame>
  );
}

