  name: string,
  title: string,
  team: Team,
  hue: Person["hue"],
  presence: Presence,
  lastActive: string,
  place: string,
  bio: string,
  focus: string,
): Person => ({
  id,
  name,
  email: `${name.toLowerCase().replace(/[^a-z]+/g, ".")}@harbourstreet.clinic`,
  title,
  team,
  hue,
  presence,
  lastActive,
  place,
  bio,
  focus,
});

